:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
  --border: #0f3460;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 3px solid var(--border);
  padding: 24px;
  box-shadow: 6px 6px 0 var(--border);
}
h1 { font-size: 1.5rem; margin-bottom: 16px; letter-spacing: 1px; }
.counts { display: flex; gap: 24px; margin-bottom: 20px; color: var(--muted); }
.counts strong { color: var(--accent); }
.input-row { display: flex; gap: 8px; margin-bottom: 20px; }
input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-size: 16px;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  outline: none;
}
input[type="text"]:focus-visible { border-color: var(--accent); }
button {
  padding: 10px 16px;
  font-size: 16px;
  background: var(--accent);
  color: #fff;
  border: 2px solid var(--accent);
  cursor: pointer;
  font-weight: 600;
}
button:hover { filter: brightness(1.15); }
button:active { transform: translate(2px, 2px); }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.todo-list { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  background: var(--bg);
  border: 2px solid var(--border);
}
.todo-item.done span { text-decoration: line-through; color: var(--muted); }
.todo-item input[type="checkbox"] { width: 20px; height: 20px; accent-color: var(--accent); cursor: pointer; flex-shrink: 0; }
.todo-item span { flex: 1; word-break: break-word; }
.todo-item .delete {
  background: transparent;
  border: 2px solid var(--muted);
  color: var(--muted);
  padding: 4px 10px;
  font-size: 14px;
  flex-shrink: 0;
}
.todo-item .delete:hover { border-color: var(--accent); color: var(--accent); }
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

(function () {
  'use strict';

  var tasks = [];
  var nextId = 1;

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('todo-add');
  var list = document.getElementById('todo-list');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');

  function updateCounts() {
    var remaining = 0;
    for (var i = 0; i < tasks.length; i++) {
      if (!tasks[i].done) remaining++;
    }
    totalEl.textContent = String(tasks.length);
    remainingEl.textContent = String(remaining);
  }

  function render() {
    list.textContent = '';
    tasks.forEach(function (task) {
      var li = document.createElement('li');
      li.className = 'todo-item' + (task.done ? ' done' : '');

      var cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.id = 'todo-check-' + task.id;
      cb.checked = task.done;
      cb.setAttribute('aria-label', 'Mark "' + task.text + '" complete');
      cb.addEventListener('change', function () {
        task.done = cb.checked;
        li.classList.toggle('done', task.done);
        updateCounts();
      });

      var span = document.createElement('span');
      span.id = 'todo-text-' + task.id;
      span.textContent = task.text;

      var del = document.createElement('button');
      del.type = 'button';
      del.id = 'todo-delete-' + task.id;
      del.className = 'delete';
      del.textContent = 'Delete';
      del.setAttribute('aria-label', 'Delete "' + task.text + '"');
      del.addEventListener('click', function () {
        tasks = tasks.filter(function (t) { return t.id !== task.id; });
        render();
      });

      li.appendChild(cb);
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });
    updateCounts();
  }

  function addTask() {
    var text = input.value.trim();
    if (!text) return;
    tasks.push({ id: nextId++, text: text, done: false });
    input.value = '';
    render();
    input.focus();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') addTask();
  });

  render();
})();
